<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/classes/GreenPortalDatabase.php';
$env=GreenPortalDatabase::env();$dbs=['gatlas_dbp','gmodelo_dbp','gmodelo2_dbp'];$services=['task','agenda','responsibility','workflow','content','ged','ia','ocr','notifications','export'];$out=['tenants'=>[],'checks'=>[]];$ok=true;
foreach($dbs as $db){
    $p=GreenPortalDatabase::connect($env,$db,'GPT');$latest=[];
    foreach($services as $service){$q=$p->prepare('SELECT status,quantidade,detalhes FROM green_service_runs WHERE banco_dados=:db AND servico=:service ORDER BY codrun DESC LIMIT 1');$q->execute(['db'=>$db,'service'=>$service]);$row=$q->fetch(PDO::FETCH_ASSOC);$latest[$service]=$row?:null;if(!$row||$row['status']!=='CONCLUIDA')$ok=false;}
    $migration=(int)$p->query("SELECT COUNT(*) FROM registros_migracao WHERE codigo_migracao='GREEN_WINDOWS_PHP_SERVICES_190' AND status='CONCLUIDA'")->fetchColumn();$asyncMigration=(int)$p->query("SELECT COUNT(*) FROM registros_migracao WHERE codigo_migracao='GREEN_ASYNC_AI_OCR_191' AND status='CONCLUIDA'")->fetchColumn();$ocrTable=(int)$p->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='green_ocr_jobs'")->fetchColumn();$invalid=(int)$p->query("SELECT COUNT(*) FROM green_service_runs WHERE banco_dados NOT IN ('gatlas_dbp','gmodelo_dbp','gmodelo2_dbp')")->fetchColumn();$duplicateAgenda=(int)$p->query("SELECT COUNT(*)-COUNT(DISTINCT codrecorrencia,referencia) FROM agenda_execucoes")->fetchColumn();$duplicateTask=(int)$p->query("SELECT COUNT(*)-COUNT(DISTINCT chave_idempotencia) FROM green_tasks")->fetchColumn();$historicalErrors=(int)$p->query("SELECT COUNT(*) FROM green_service_runs WHERE status='ERRO'")->fetchColumn();
    $errorQuery=$p->prepare("SELECT COUNT(*) FROM (SELECT servico,MAX(codrun) codrun FROM green_service_runs WHERE banco_dados=:db GROUP BY servico) x INNER JOIN green_service_runs r ON r.codrun=x.codrun WHERE r.status='ERRO'");$errorQuery->execute(['db'=>$db]);$latestErrors=(int)$errorQuery->fetchColumn();
    $out['tenants'][$db]=['services'=>$latest,'migration_190'=>$migration,'migration_191'=>$asyncMigration,'ocr_table'=>$ocrTable,'invalid_tenant_rows'=>$invalid,'duplicate_agenda_execution_rows'=>max(0,$duplicateAgenda),'duplicate_task_keys'=>max(0,$duplicateTask),'latest_error_runs'=>$latestErrors,'historical_error_runs'=>$historicalErrors];
    if($migration!==1||$asyncMigration!==1||$ocrTable!==1||$invalid!==0||$duplicateAgenda!==0||$duplicateTask!==0||$latestErrors!==0)$ok=false;
}
$out['checks']=['last_runs_concluidas'=>$ok,'processamento_nos_tres_tenants'=>count($out['tenants'])===3,'isolamento_tenant'=>array_sum(array_map(fn($x)=>(int)$x['invalid_tenant_rows'],$out['tenants']))===0,'idempotencia_sem_duplicidades'=>array_sum(array_map(fn($x)=>(int)$x['duplicate_agenda_execution_rows']+(int)$x['duplicate_task_keys'],$out['tenants']))===0,'erros_registrados'=>array_sum(array_map(fn($x)=>(int)$x['latest_error_runs'],$out['tenants']))===0,'historico_de_erros'=>array_sum(array_map(fn($x)=>(int)$x['historical_error_runs'],$out['tenants']))];$out['ok']=($ok&&$out['checks']['processamento_nos_tres_tenants']);echo json_encode($out,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT).PHP_EOL;exit($out['ok']?0:1);
